ruleContent.nextContentUrl:
@js:
if (result.indexOf("nextpage.png") > -1) {
  var code = result.match(/eval\(function(.*)\);/)[0];
  code = code.replace(/u[0-9a-f]{10,}/, 'uData')
  var uData = ''; 
  eval(code);

  if(!uData.match('_')) {
	next = java.getElement("@@#pt_next@a")
	uData = next.attr("href")
	}

  uData;
}

ruleSearch.bookList:
body > div.wrap > div > ul > dl
<js>
list = result;
h = java.getStringList("li > span.s2 > a@href", list);

ht = h[1].includes("http") ? Array.from(h) : Array.from(h, x => `${source.key}${x}`);

d = java.ajaxAll(ht).map(x => x.body());

$=(b,c)=>java.getString(b,c);

Array.from(list,(a,i)=>{
	list={
		name:$("li a@text",a),
		author:$("li > span.s3@text",a),
		kind:$("li > span.s1@text",a),
		update:$("p:nth-child(8) > a@text, d[i]"),
		intro:$("body > div.cover > div:nth-child(7)@html",d[i]),
		cover:$("img@src",d[i]),
		link:$("li > span.s2 > a@href" ,a)
		};
		return list
	});
</js>

